package com.bank.risk;

import java.util.Arrays;
import java.util.logging.Logger;

// Groups risk-tagged transactions (0=low,1=med,2=high) for National Bank of India.
public class RiskSorter {
    private static final Logger log = Logger.getLogger(RiskSorter.class.getName());

    // Dutch National Flag: single-pass three-way partition. O(n), O(1).
    public void sortRiskBuckets(int[] risk) {
        if (risk == null || risk.length < 2) return;
        int low = 0;                 // next position for a 0
        int mid = 0;                 // scanning pointer
        int high = risk.length - 1;  // next position for a 2
        while (mid <= high) {
            switch (risk[mid]) {
                case 0 -> {
                    swap(risk, low, mid);
                    low++;
                    mid++;           // swapped-in value already processed → advance
                }
                case 1 -> mid++;     // 1 belongs in the middle → just scan on
                case 2 -> {
                    swap(risk, mid, high);
                    high--;          // do NOT advance mid: new value is unknown
                }
                default -> throw new IllegalArgumentException("risk must be 0,1,2 but was " + risk[mid]);
            }
        }
        log.info(() -> "Grouped risk buckets: " + Arrays.toString(risk));
    }

    private void swap(int[] a, int i, int j) {
        int t = a[i];
        a[i] = a[j];
        a[j] = t;
    }
}
