package com.bank.risk;

import java.util.Arrays;
import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

// Runnable demo: group a day's risk-tagged transactions.
public class RiskDemo {
    private static final Logger log = Logger.getLogger(RiskDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        RiskSorter sorter = new RiskSorter();

        // Rajesh (SAV2001) day's transaction risk tags, unsorted.
        int[] risk = {2, 0, 1, 2, 1, 0, 0, 2, 1};
        log.info(() -> "Before: " + Arrays.toString(risk));
        sorter.sortRiskBuckets(risk);
        log.info(() -> "After (low→med→high): " + Arrays.toString(risk));
    }
}
